<?php
namespace App\Services;
use App\Models\BitacoraAuditoria; use Illuminate\Http\Request;
class AuditoriaService { public function registrar(Request $request,string $evento):BitacoraAuditoria { return \Illuminate\Support\Facades\DB::transaction(function()use($request,$evento){if(\Illuminate\Support\Facades\DB::getDriverName()==='pgsql')\Illuminate\Support\Facades\DB::select("select pg_advisory_xact_lock(hashtext('aquarium_audit_chain'))");$prev=BitacoraAuditoria::latest('id')->value('hash_inmutable')??str_repeat('0',64);$date=now();$hash=hash('sha256',implode('|',[$prev,$request->user()?->id??'',$evento,$request->ip()??'',$date->toISOString()]));return BitacoraAuditoria::create(['user_id'=>$request->user()?->id,'evento'=>$evento,'ip_address'=>$request->ip(),'fecha_hora'=>$date,'hash_inmutable'=>$hash]);}); } }
